create extension if not exists pgcrypto;
create type public.organization_role as enum ('owner', 'admin', 'agronomist', 'operator', 'viewer');
create table public.organizations (id uuid primary key default gen_random_uuid(), name text not null check (char_length(name) between 2 and 120), created_at timestamptz not null default now());
create table public.organization_members (organization_id uuid not null references public.organizations(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role public.organization_role not null default 'viewer', created_at timestamptz not null default now(), primary key (organization_id,user_id));
create table public.establishments (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, name text not null, latitude double precision not null check (latitude between -90 and 90), longitude double precision not null check (longitude between -180 and 180), area_hectares numeric(12,2) check (area_hectares >= 0), created_at timestamptz not null default now());
create table public.devices (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, establishment_id uuid not null references public.establishments(id) on delete cascade, external_id text not null, kind text not null check (kind in ('gateway','weather','soil','rfid','camera','machine','water')), status text not null default 'provisioning' check (status in ('provisioning','online','offline','retired')), last_seen_at timestamptz, created_at timestamptz not null default now(), unique(organization_id,external_id));
create table public.sensor_readings (id bigint generated always as identity primary key, organization_id uuid not null references public.organizations(id) on delete cascade, device_id uuid not null references public.devices(id) on delete cascade, observed_at timestamptz not null, metric text not null, value double precision not null, unit text not null, quality smallint not null default 100 check (quality between 0 and 100), ingested_at timestamptz not null default now(), unique(device_id,observed_at,metric));
create index sensor_readings_device_time_idx on public.sensor_readings(device_id,observed_at desc);
alter table public.organizations enable row level security; alter table public.organization_members enable row level security; alter table public.establishments enable row level security; alter table public.devices enable row level security; alter table public.sensor_readings enable row level security;
revoke all on public.organizations,public.organization_members,public.establishments,public.devices,public.sensor_readings from anon,authenticated;
grant select on public.organizations,public.organization_members,public.establishments,public.devices,public.sensor_readings to authenticated;
grant insert,update,delete on public.establishments,public.devices to authenticated;
create policy organizations_select_member on public.organizations for select to authenticated using (exists(select 1 from public.organization_members m where m.organization_id=id and m.user_id=(select auth.uid())));
create policy memberships_select on public.organization_members for select to authenticated using (user_id=(select auth.uid()) or exists(select 1 from public.organization_members m where m.organization_id=organization_members.organization_id and m.user_id=(select auth.uid()) and m.role in ('owner','admin')));
create policy establishments_select on public.establishments for select to authenticated using (exists(select 1 from public.organization_members m where m.organization_id=establishments.organization_id and m.user_id=(select auth.uid())));
create policy establishments_insert on public.establishments for insert to authenticated with check (exists(select 1 from public.organization_members m where m.organization_id=establishments.organization_id and m.user_id=(select auth.uid()) and m.role in ('owner','admin')));
create policy establishments_update on public.establishments for update to authenticated using (exists(select 1 from public.organization_members m where m.organization_id=establishments.organization_id and m.user_id=(select auth.uid()) and m.role in ('owner','admin'))) with check (exists(select 1 from public.organization_members m where m.organization_id=establishments.organization_id and m.user_id=(select auth.uid()) and m.role in ('owner','admin')));
create policy establishments_delete on public.establishments for delete to authenticated using (exists(select 1 from public.organization_members m where m.organization_id=establishments.organization_id and m.user_id=(select auth.uid()) and m.role='owner'));
create policy devices_select on public.devices for select to authenticated using (exists(select 1 from public.organization_members m where m.organization_id=devices.organization_id and m.user_id=(select auth.uid())));
create policy devices_insert on public.devices for insert to authenticated with check (exists(select 1 from public.organization_members m where m.organization_id=devices.organization_id and m.user_id=(select auth.uid()) and m.role in ('owner','admin')));
create policy devices_update on public.devices for update to authenticated using (exists(select 1 from public.organization_members m where m.organization_id=devices.organization_id and m.user_id=(select auth.uid()) and m.role in ('owner','admin')));
create policy devices_delete on public.devices for delete to authenticated using (exists(select 1 from public.organization_members m where m.organization_id=devices.organization_id and m.user_id=(select auth.uid()) and m.role='owner'));
create policy readings_select on public.sensor_readings for select to authenticated using (exists(select 1 from public.organization_members m where m.organization_id=sensor_readings.organization_id and m.user_id=(select auth.uid())));
comment on table public.sensor_readings is 'Append-only observations ingested by a trusted server or device-token service, never by the browser.';
